        "content": "/**\n * Bun utility script that validates JSON input from stdin.\n *\n * Usage: echo '{\"key\":\"value\"}' | bun run src/validate-json.ts\n *\n * Exit codes:\n *   0 - Valid JSON\n *   1 - Invalid or empty input\n */\n\nasync function main(): Promise<void> {\n  const chunks: Uint8Array[] = [];\n\n  for await (const chunk of Bun.stdin.stream()) {\n    chunks.push(chunk);\n  }\n\n  const input = Buffer.concat(chunks).toString(\"utf-8\").trim();\n\n  if (input.length === 0) {\n    console.error(\"Error: No input provided. Please pipe JSON to stdin.\");\n    process.exit(1);\n  }\n\n  try {\n    JSON.parse(input);\n    console.log(\"Valid JSON\");\n    process.exit(0);\n  } catch (error) {\n    const message = error instanceof SyntaxError ? error.message : \"Unknown parse error\";\n    console.error(`Invalid JSON: ${message}`);\n    process.exit(1);\n  }\n}\n\nmain();\n"
