\"]),\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n\n    const exitCode = await proc.exited;\n    const stderr = await new Response(proc.stderr).text();\n\n    expect(exitCode).toBe(1);\n    expect(stderr.trim()).toContain(\"No input provided\");\n  });\n});\n"
