/**
 * Bun utility script that validates JSON input from stdin.
 *
 * Usage: echo '{"key":"value"}' | bun run src/validate-json.ts
 *
 * Exit codes:
 *   0 - Valid JSON
 *   1 - Invalid or empty input
 */

async function main(): Promise<void> {
  const chunks: Uint8Array[] = [];

  for await (const chunk of Bun.stdin.stream()) {
    chunks.push(chunk);
  }

  const input = Buffer.concat(chunks).toString("utf-8").trim();

  if (input.length === 0) {
    console.error("Error: No input provided. Please pipe JSON to stdin.");
    process.exit(1);
  }

  try {
    JSON.parse(input);
    console.log("Valid JSON");
    process.exit(0);
  } catch (error) {
    const message = error instanceof SyntaxError ? error.message : "Unknown parse error";
    console.error(`Invalid JSON: ${message}`);
    process.exit(1);
  }
}

main();

import { describe, expect, test } from "bun:test";

describe("validate-json", () => {
  const scriptPath = new URL("./validate-json.ts", import.meta.url).pathname;

  test("accepts valid JSON object", async () => {
    const proc = Bun.spawn(["bun", "run", scriptPath], {
      stdin: new Blob(['{"name": "test", "value": 42}']),
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    const stdout = await new Response(proc.stdout).text();

    expect(exitCode).toBe(0);
    expect(stdout.trim()).toBe("Valid JSON");
  });

  test("accepts valid JSON array", async () => {
    const proc = Bun.spawn(["bun", "run", scriptPath], {
      stdin: new Blob(['[1, 2, 3]']),
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    const stdout = await new Response(proc.stdout).text();

    expect(exitCode).toBe(0);
    expect(stdout.trim()).toBe("Valid JSON");
  });

  test("accepts valid JSON string", async () => {
    const proc = Bun.spawn(["bun", "run", scriptPath], {
      stdin: new Blob(['"hello world"']),
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    const stdout = await new Response(proc.stdout).text();

    expect(exitCode).toBe(0);
    expect(stdout.trim()).toBe("Valid JSON");
  });

  test("rejects invalid JSON", async () => {
    const proc = Bun.spawn(["bun", "run", scriptPath], {
      stdin: new Blob(["{not valid json}"]),
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    const stderr = await new Response(proc.stderr).text();

    expect(exitCode).toBe(1);
    expect(stderr.trim()).toContain("Invalid JSON");
  });

  test("rejects empty input", async () => {
    const proc = Bun.spawn(["bun", "run", scriptPath], {
      stdin: new Blob([""]),
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    const stderr = await new Response(proc.stderr).text();

    expect(exitCode).toBe(1);
    expect(stderr.trim()).toContain("No input provided");
  });
});

