import { describe, expect, test } from "bun:test";
import { greet, farewell, add } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("farewell returns goodbye message", () => {
    expect(farewell("Alice")).toBe("Goodbye, Alice!");
  });

  test("farewell handles empty string", () => {
    expect(farewell("")).toBe("Goodbye, !");
  });

  test("farewell handles names with spaces", () => {
    expect(farewell("John Doe")).toBe("Goodbye, John Doe!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

