/**
 * Ultra-performant JSON validator using character-by-character scanning.
 * Validates JSON strings without allocating intermediate objects.
 */

export interface ValidationError {
  message: string;
  position: number;
  line: number;
  column: number;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

// Pre-computed lookup tables for performance
const WHITESPACE = new Uint8Array(128);
WHITESPACE[0x20] = 1; // space
WHITESPACE[0x09] = 1; // tab
WHITESPACE[0x0a] = 1; // newline
WHITESPACE[0x0d] = 1; // carriage return

const ESCAPE_CHARS = new Uint8Array(128);
ESCAPE_CHARS[0x22] = 1; // "
ESCAPE_CHARS[0x5c] = 1; // \
ESCAPE_CHARS[0x2f] = 1; // /
ESCAPE_CHARS[0x62] = 1; // b
ESCAPE_CHARS[0x66] = 1; // f
ESCAPE_CHARS[0x6e] = 1; // n
ESCAPE_CHARS[0x72] = 1; // r
ESCAPE_CHARS[0x74] = 1; // t
ESCAPE_CHARS[0x75] = 1; // u

const HEX_CHARS = new Uint8Array(128);
for (let i = 48; i <= 57; i++) HEX_CHARS[i] = 1;  // 0-9
for (let i = 65; i <= 70; i++) HEX_CHARS[i] = 1;  // A-F
for (let i = 97; i <= 102; i++) HEX_CHARS[i] = 1; // a-f

const DIGIT_CHARS = new Uint8Array(128);
for (let i = 48; i <= 57; i++) DIGIT_CHARS[i] = 1; // 0-9

class JsonValidator {
  private input: string;
  private pos: number;
  private len: number;
  private line: number;
  private col: number;
  private errors: ValidationError[];

  constructor(input: string) {
    this.input = input;
    this.pos = 0;
    this.len = input.length;
    this.line = 1;
    this.col = 1;
    this.errors = [];
  }

  validate(): ValidationResult {
    if (this.len === 0) {
      this.addError("Unexpected end of input");
      return { valid: false, errors: this.errors };
    }

    this.skipWhitespace();

    if (this.pos >= this.len) {
      this.addError("Unexpected end of input");
      return { valid: false, errors: this.errors };
    }

    this.parseValue();

    if (this.errors.length === 0) {
      this.skipWhitespace();
      if (this.pos < this.len) {
        this.addError(`Unexpected character '${this.input[this.pos]}' after valid JSON`);
      }
    }

    return {
      valid: this.errors.length === 0,
      errors: this.errors,
    };
  }

  private addError(message: string): void {
    this.errors.push({
      message,
      position: this.pos,
      line: this.line,
      column: this.col,
    });
  }

  private peek(): number {
    if (this.pos >= this.len) return -1;
    return this.input.charCodeAt(this.pos);
  }

  private advance(): number {
    if (this.pos >= this.len) return -1;
    const ch = this.input.charCodeAt(this.pos);
    this.pos++;
    if (ch === 0x0a) {
      this.line++;
      this.col = 1;
    } else {
      this.col++;
    }
    return ch;
  }

  private skipWhitespace(): void {
    while (this.pos < this.len) {
      const ch = this.input.charCodeAt(this.pos);
      if (ch < 128 && WHITESPACE[ch]) {
        this.advance();
      } else {
        break;
      }
    }
  }

  private expect(charCode: number): boolean {
    if (this.peek() === charCode) {
      this.advance();
      return true;
    }
    return false;
  }

  private parseValue(): void {
    if (this.errors.length > 0) return;

    this.skipWhitespace();

    if (this.pos >= this.len) {
      this.addError("Unexpected end of input");
      return;
    }

    const ch = this.peek();

    switch (ch) {
      case 0x7b: // {
        this.parseObject();
        break;
      case 0x5b: // [
        this.parseArray();
        break;
      case 0x22: // "
        this.parseString();
        break;
      case 0x74: // t (true)
        this.parseLiteral("true");
        break;
      case 0x66: // f (false)
        this.parseLiteral("false");
        break;
      case 0x6e: // n (null)
        this.parseLiteral("null");
        break;
      case 0x2d: // - (negative number)
        this.parseNumber();
        break;
      default:
        if (ch >= 0x30 && ch <= 0x39) {
          this.parseNumber();
        } else {
          this.addError(`Unexpected character '${this.input[this.pos]}'`);
        }
        break;
    }
  }

  private parseObject(): void {
    this.advance(); // consume {
    this.skipWhitespace();

    if (this.expect(0x7d)) return; // empty object }

    const seenKeys = new Set<string>();

    while (this.errors.length === 0) {
      this.skipWhitespace();

      if (this.pos >= this.len) {
        this.addError("Unexpected end of input in object");
        return;
      }

      // Check for trailing comma
      if (this.peek() === 0x7d) {
        this.addError("Trailing comma in object");
        return;
      }

      if (this.peek() !== 0x22) {
        this.addError(`Expected string key, got '${this.input[this.pos]}'`);
        return;
      }

      const keyStart = this.pos + 1;
      this.parseString();
      if (this.errors.length > 0) return;

      const keyEnd = this.pos - 1; // before closing quote
      const key = this.input.slice(keyStart, keyEnd);

      if (seenKeys.has(key)) {
        this.addError(`Duplicate key "${key}"`);
        return;
      }
      seenKeys.add(key);

      this.skipWhitespace();

      if (!this.expect(0x3a)) { // :
        this.addError(
          this.pos < this.len
            ? `Expected ':' after key, got '${this.input[this.pos]}'`
            : "Unexpected end of input, expected ':'"
        );
        return;
      }

      this.skipWhitespace();
      this.parseValue();
      if (this.errors.length > 0) return;

      this.skipWhitespace();

      if (this.expect(0x7d)) return; // }
      if (!this.expect(0x2c)) { // ,
        this.addError(
          this.pos < this.len
            ? `Expected ',' or '}', got '${this.input[this.pos]}'`
            : "Unexpected end of input in object"
        );
        return;
      }
    }
  }

  private parseArray(): void {
    this.advance(); // consume [
    this.skipWhitespace();

    if (this.expect(0x5d)) return; // empty array ]

    while (this.errors.length === 0) {
      this.skipWhitespace();

      // Check for trailing comma
      if (this.peek() === 0x5d) {
        this.addError("Trailing comma in array");
        return;
      }

      this.parseValue();
      if (this.errors.length > 0) return;

      this.skipWhitespace();

      if (this.expect(0x5d)) return; // ]
      if (!this.expect(0x2c)) { // ,
        this.addError(
          this.pos < this.len
            ? `Expected ',' or ']', got '${this.input[this.pos]}'`
            : "Unexpected end of input in array"
        );
        return;
      }
    }
  }

  private parseString(): void {
    if (!this.expect(0x22)) { // "
      this.addError("Expected '\"'");
      return;
    }

    while (this.pos < this.len) {
      const ch = this.advance();

      if (ch === 0x22) return; // closing "

      if (ch === 0x5c) { // backslash
        if (this.pos >= this.len) {
          this.addError("Unexpected end of input in string escape");
          return;
        }
        const esc = this.peek();
        if (esc < 128 && ESCAPE_CHARS[esc]) {
          this.advance();
          if (esc === 0x75) { // \u
            for (let i = 0; i < 4; i++) {
              if (this.pos >= this.len) {
                this.addError("Unexpected end of input in unicode escape");
                return;
              }
              const hex = this.peek();
              if (hex >= 128 || !HEX_CHARS[hex]) {
                this.addError(`Invalid unicode escape character '${this.input[this.pos]}'`);
                return;
              }
              this.advance();
            }
          }
        } else {
          this.addError(`Invalid escape character '${this.input[this.pos]}'`);
          return;
        }
        continue;
      }

      // Control characters are not allowed in strings
      if (ch < 0x20) {
        this.addError("Invalid control character in string");
        return;
      }
    }

    this.addError("Unterminated string");
  }

  private parseNumber(): void {
    const start = this.pos;

    // Optional minus
    if (this.peek() === 0x2d) this.advance();

    if (this.pos >= this.len) {
      this.addError("Unexpected end of input in number");
      return;
    }

    // Integer part
    const firstDigit = this.peek();
    if (firstDigit === 0x30) { // leading zero
      this.advance();
      // After a leading zero, only '.', 'e', 'E', or end of number is valid
      const next = this.peek();
      if (next >= 0x30 && next <= 0x39) {
        this.addError("Leading zeros are not allowed");
        return;
      }
    } else if (firstDigit >= 0x31 && firstDigit <= 0x39) {
      this.advance();
      while (this.pos < this.len) {
        const ch = this.peek();
        if (ch < 128 && DIGIT_CHARS[ch]) {
          this.advance();
        } else {
          break;
        }
      }
    } else {
      this.addError(`Invalid number character '${this.input[this.pos]}'`);
      return;
    }

    // Fractional part
    if (this.peek() === 0x2e) { // .
      this.advance();
      if (this.pos >= this.len) {
        this.addError("Unexpected end of input after decimal point");
        return;
      }
      const ch = this.peek();
      if (ch < 0x30 || ch > 0x39) {
        this.addError("Expected digit after decimal point");
        return;
      }
      while (this.pos < this.len) {
        const ch = this.peek();
        if (ch < 128 && DIGIT_CHARS[ch]) {
          this.advance();
        } else {
          break;
        }
      }
    }

    // Exponent part
    const expCh = this.peek();
    if (expCh === 0x65 || expCh === 0x45) { // e or E
      this.advance();
      const sign = this.peek();
      if (sign === 0x2b || sign === 0x2d) this.advance(); // + or -
      if (this.pos >= this.len) {
        this.addError("Unexpected end of input in exponent");
        return;
      }
      const ch = this.peek();
      if (ch < 0x30 || ch > 0x39) {
        this.addError("Expected digit in exponent");
        return;
      }
      while (this.pos < this.len) {
        const ch = this.peek();
        if (ch < 128 && DIGIT_CHARS[ch]) {
          this.advance();
        } else {
          break;
        }
      }
    }

    if (this.pos === start) {
      this.addError("Invalid number");
    }
  }

  private parseLiteral(expected: string): void {
    for (let i = 0; i < expected.length; i++) {
      if (this.pos >= this.len) {
        this.addError(`Unexpected end of input, expected '${expected}'`);
        return;
      }
      if (this.input.charCodeAt(this.pos) !== expected.charCodeAt(i)) {
        this.addError(`Expected '${expected}', got '${this.input.slice(this.pos - i, this.pos - i + expected.length)}'`);
        return;
      }
      this.advance();
    }
  }
}

/**
 * Validate a JSON string without parsing it into objects.
 * Uses character-by-character scanning for maximum performance.
 */
export function validateJson(input: string): ValidationResult {
  return new JsonValidator(input).validate();
}

import { describe, expect, test } from "bun:test";
import { validateJson } from "./json-validator";

describe("json-validator", () => {
  describe("valid JSON", () => {
    test("empty object", () => {
      const result = validateJson("{}");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("empty array", () => {
      const result = validateJson("[]");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("simple object", () => {
      const result = validateJson('{"name": "Alice", "age": 30}');
      expect(result.valid).toBe(true);
    });

    test("simple array", () => {
      const result = validateJson("[1, 2, 3]");
      expect(result.valid).toBe(true);
    });

    test("string value", () => {
      const result = validateJson('"hello"');
      expect(result.valid).toBe(true);
    });

    test("number values", () => {
      expect(validateJson("42").valid).toBe(true);
      expect(validateJson("-17").valid).toBe(true);
      expect(validateJson("3.14").valid).toBe(true);
      expect(validateJson("2.998e8").valid).toBe(true);
      expect(validateJson("-1.5E+3").valid).toBe(true);
      expect(validateJson("0").valid).toBe(true);
      expect(validateJson("0.5").valid).toBe(true);
    });

    test("boolean values", () => {
      expect(validateJson("true").valid).toBe(true);
      expect(validateJson("false").valid).toBe(true);
    });

    test("null", () => {
      expect(validateJson("null").valid).toBe(true);
    });

    test("nested structures", () => {
      const json = '{"users": [{"name": "Bob", "scores": [1, 2, 3]}, {"name": "Eve", "scores": []}]}';
      expect(validateJson(json).valid).toBe(true);
    });

    test("deeply nested arrays", () => {
      const json = "[[[[[[1]]]]]]";
      expect(validateJson(json).valid).toBe(true);
    });

    test("string with escape sequences", () => {
      const json = '"hello\\nworld\\t\\"escaped\\"\\\\path\\/slash"';
      expect(validateJson(json).valid).toBe(true);
    });

    test("string with unicode escapes", () => {
      const json = '"\\u0041\\u0042\\u0043"';
      expect(validateJson(json).valid).toBe(true);
    });

    test("whitespace handling", () => {
      const json = '  {  "key"  :  "value"  }  ';
      expect(validateJson(json).valid).toBe(true);
    });

    test("multiline JSON", () => {
      const json = `{
  "name": "test",
  "value": 42
}`;
      expect(validateJson(json).valid).toBe(true);
    });

    test("large number", () => {
      expect(validateJson("9999999999999999999999").valid).toBe(true);
    });

    test("negative zero", () => {
      expect(validateJson("-0").valid).toBe(true);
    });

    test("exponent notation", () => {
      expect(validateJson("1e10").valid).toBe(true);
      expect(validateJson("1E10").valid).toBe(true);
      expect(validateJson("1e+10").valid).toBe(true);
      expect(validateJson("1e-10").valid).toBe(true);
    });
  });

  describe("invalid JSON", () => {
    test("empty string", () => {
      const result = validateJson("");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("trailing comma in object", () => {
      const result = validateJson('{"a": 1,}');
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Trailing comma");
    });

    test("trailing comma in array", () => {
      const result = validateJson("[1, 2,]");
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Trailing comma");
    });

    test("single quotes", () => {
      const result = validateJson("{'key': 'value'}");
      expect(result.valid).toBe(false);
    });

    test("unquoted keys", () => {
      const result = validateJson("{key: 1}");
      expect(result.valid).toBe(false);
    });

    test("truncated object", () => {
      const result = validateJson('{"key": ');
      expect(result.valid).toBe(false);
    });

    test("truncated array", () => {
      const result = validateJson("[1, 2, ");
      expect(result.valid).toBe(false);
    });

    test("truncated string", () => {
      const result = validateJson('"hello');
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Unterminated string");
    });

    test("invalid escape sequence", () => {
      const result = validateJson('"hello\\x"');
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Invalid escape");
    });

    test("incomplete unicode escape", () => {
      const result = validateJson('"\\u00"');
      expect(result.valid).toBe(false);
    });

    test("invalid unicode escape characters", () => {
      const result = validateJson('"\\uGGGG"');
      expect(result.valid).toBe(false);
    });

    test("leading zeros in numbers", () => {
      const result = validateJson("01");
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Leading zeros");
    });

    test("trailing content", () => {
      const result = validateJson("{}[]");
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Unexpected character");
    });

    test("just a comma", () => {
      const result = validateJson(",");
      expect(result.valid).toBe(false);
    });

    test("missing colon in object", () => {
      const result = validateJson('{"key" "value"}');
      expect(result.valid).toBe(false);
    });

    test("duplicate keys", () => {
      const result = validateJson('{"a": 1, "a": 2}');
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Duplicate key");
    });

    test("bare value (not a valid token)", () => {
      const result = validateJson("undefined");
      expect(result.valid).toBe(false);
    });

    test("NaN is not valid JSON", () => {
      const result = validateJson("NaN");
      expect(result.valid).toBe(false);
    });

    test("Infinity is not valid JSON", () => {
      const result = validateJson("Infinity");
      expect(result.valid).toBe(false);
    });

    test("control character in string", () => {
      const result = validateJson('"hello\tworld"');
      expect(result.valid).toBe(false);
    });

    test("number with trailing dot", () => {
      const result = validateJson("1.");
      expect(result.valid).toBe(false);
    });

    test("number with leading dot", () => {
      const result = validateJson(".5");
      expect(result.valid).toBe(false);
    });
  });

  describe("error reporting", () => {
    test("reports correct position for error", () => {
      const result = validateJson('{"key": }');
      expect(result.valid).toBe(false);
      expect(result.errors[0].position).toBe(8);
    });

    test("reports correct line and column", () => {
      const json = '{\n  "key": ,\n}';
      const result = validateJson(json);
      expect(result.valid).toBe(false);
      expect(result.errors[0].line).toBe(2);
    });

    test("error includes descriptive message", () => {
      const result = validateJson("{invalid}");
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toBeTruthy();
      expect(result.errors[0].message.length).toBeGreaterThan(0);
    });
  });

  describe("performance", () => {
    test("validates large JSON array within 50ms", () => {
      const items = Array.from({ length: 10000 }, (_, i) =>
        `{"id": ${i}, "name": "item-${i}", "value": ${Math.random()}}`
      );
      const largeJson = `[${items.join(",")}]`;

      const start = performance.now();
      const result = validateJson(largeJson);
      const elapsed = performance.now() - start;

      expect(result.valid).toBe(true);
      expect(elapsed).toBeLessThan(50);
    });

    test("validates deeply nested structure", () => {
      const depth = 100;
      const open = "[".repeat(depth);
      const close = "]".repeat(depth);
      const json = `${open}1${close}`;

      const start = performance.now();
      const result = validateJson(json);
      const elapsed = performance.now() - start;

      expect(result.valid).toBe(true);
      expect(elapsed).toBeLessThan(10);
    });
  });
});

/**
 * Main entry point for the rp1 eval test project.
 */

import { greet } from "./utils";
import { validateJson } from "./json-validator";

const args = process.argv.slice(2);

if (args[0] === "--validate-json") {
  const target = args[1];

  if (!target) {
    console.error("Usage: --validate-json <file | ->");
    process.exit(1);
  }

  let input: string;

  if (target === "-") {
    input = await Bun.stdin.text();
  } else {
    const file = Bun.file(target);
    if (!(await file.exists())) {
      console.error(`File not found: ${target}`);
      process.exit(1);
    }
    input = await file.text();
  }

  const result = validateJson(input);

  if (result.valid) {
    console.log("\x1b[32m✓ Valid JSON\x1b[0m");
  } else {
    console.log("\x1b[31m✗ Invalid JSON\x1b[0m");
    for (const error of result.errors) {
      console.log(`  Line ${error.line}, Column ${error.column}: ${error.message}`);
    }
    process.exit(1);
  }
} else {
  const name = args[0] ?? "World";
  console.log(greet(name));
}

