if (askCall) return { pass: false, score: 0, reason: 'Found AskUserQuestion in AFK mode — should be bypassed' };
return { pass: true, score: 1, reason: 'No AskUserQuestion calls in AFK mode' };

// Assert task-builder spawned
const meta = context.providerResponse?.metadata;
const tcs = meta?.toolCalls ?? [];
const hasSubagent = tcs.some(tc =>
  ['Task', 'task', 'Agent', 'agent'].includes(tc.name) &&
  JSON.stringify(tc.input).includes('task-builder')
);
if (!hasSubagent) return { pass: false, score: 0, reason: 'No task-builder subagent spawn found' };
return { pass: true, score: 1, reason: 'task-builder spawned' };

// Assert artifact registration
const meta = context.providerResponse?.metadata;
const cmds = meta?.bashCommands ?? [];
const hasArtifact = cmds.some(c => c.includes('rp1 agent-tools work artifact') && c.includes('--project') && c.includes('--run-id') && c.includes('--path'));
if (!hasArtifact) return { pass: false, score: 0, reason: 'No artifact registration found' };
return { pass: true, score: 1, reason: 'Artifact registration found' };
